{
  "findings": [
    {
      "check_id": "CKV_AWS_53",
      "title": "Ensure S3 bucket has block public ACLS enabled",
      "resource": "aws_s3_bucket_public_access_block.api_docs",
      "severity": "CRITICAL",
      "explanation": "The 'block_public_acls' attribute is missing, which could allow public ACLs to be applied to the bucket, exposing sensitive data."
    },
    {
      "check_id": "CKV_AWS_54",
      "title": "Ensure S3 bucket has block public policy enabled",
      "resource": "aws_s3_bucket_public_access_block.api_docs",
      "severity": "MEDIUM",
      "explanation": "The 'block_public_policy' attribute is missing, which could allow public bucket policies to be applied, increasing the risk of data exposure."
    },
    {
      "check_id": "CKV_AWS_55",
      "title": "Ensure S3 bucket has ignore public ACLs enabled",
      "resource": "aws_s3_bucket_public_access_block.api_docs",
      "severity": "MEDIUM",
      "explanation": "The 'ignore_public_acls' attribute is missing, which could allow public ACLs to be honored, potentially exposing the bucket to public access."
    },
    {
      "check_id": "CKV_AWS_56",
      "title": "Ensure S3 bucket has 'restrict_public_buckets' enabled",
      "resource": "aws_s3_bucket_public_access_block.api_docs",
      "severity": "MEDIUM",
      "explanation": "The 'restrict_public_buckets' attribute is explicitly set to 'false', which allows public bucket policies, increasing the risk of data exposure."
    }
  ],
  "patched_code": "resource \"aws_s3_bucket_public_access_block\" \"api_docs\" {\n  bucket = aws_s3_bucket.api_docs.id\n\n  block_public_acls   = true\n  block_public_policy = true\n  ignore_public_acls  = true\n  restrict_public_buckets = true\n}",
  "fix_summary": "Added 'block_public_acls', 'block_public_policy', and 'ignore_public_acls' attributes with 'true' values to block public access. Changed 'restrict_public_buckets' from 'false' to 'true' to prevent public bucket policies."
}
